"""Auto-generated file processor calls for any owner, with the v2 DTOs and the legacy dotfile
DTOs."""

from ai.backend.common.contexts.user import current_user
from ai.backend.common.data.entity.domain import DomainEntityType, DomainID
from ai.backend.common.data.entity.project import ProjectEntityType, ProjectID
from ai.backend.common.data.entity.types import EntityIdentifier
from ai.backend.common.data.entity.user import UserEntityType, UserID
from ai.backend.common.data.filter_specs import StringMatchSpec
from ai.backend.common.dotfile import DotfilePath
from ai.backend.common.dto.manager.config.response import (
    DeleteDotfileResponse,
    DotfileListItem,
    GetDotfileResponse,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    AutoGeneratedFileScopeInput,
    PurgeAutoGeneratedFileInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    CreateAutoGeneratedFileInput as V2CreateAutoGeneratedFileInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.response import (
    AutoGeneratedFileNode,
    CreateAutoGeneratedFilePayload,
    PurgeAutoGeneratedFilePayload,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.types import AutoGeneratedFileScopeType
from ai.backend.common.exception import UnreachableError
from ai.backend.manager.data.auto_generated_file.types import (
    AutoGeneratedFileData,
    AutoGeneratedFileRevisionSpec,
)
from ai.backend.manager.data.dotfile.types import DotfileEntry
from ai.backend.manager.dto.auto_generated_file_input import (
    CreateAutoGeneratedFileInput,
    DeleteDefaultAutoGeneratedFileInput,
    UpdateDefaultAutoGeneratedFileInput,
)
from ai.backend.manager.errors.storage import DefaultDotfilePurgeForbidden, DotfileNotFound
from ai.backend.manager.models.auto_generated_file.creators import AutoGeneratedFileCreator
from ai.backend.manager.models.auto_generated_file.scopes import AutoGeneratedFileTarget
from ai.backend.manager.models.auto_generated_file.searchable_fields import (
    AutoGeneratedFileSearchableFields,
)
from ai.backend.manager.models.auto_generated_file.searchers import AutoGeneratedFileSearcher
from ai.backend.manager.models.specs.pagination import NoPagination
from ai.backend.manager.services.auto_generated_file.actions.create import (
    CreateAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.get import (
    GetAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.get_current_revisions import (
    GetCurrentAutoGeneratedFileRevisionsAction,
)
from ai.backend.manager.services.auto_generated_file.actions.purge import (
    PurgeAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.search import (
    SearchAutoGeneratedFilesAction,
)
from ai.backend.manager.services.auto_generated_file.actions.switch_default import (
    SwitchDefaultAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.update import (
    UpdateAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.processors import AutoGeneratedFileProcessors


class AutoGeneratedFileAdapter:
    _auto_generated_file: AutoGeneratedFileProcessors

    def __init__(self, auto_generated_file: AutoGeneratedFileProcessors) -> None:
        self._auto_generated_file = auto_generated_file

    async def _search_default_auto_generated_files(
        self, owner: EntityIdentifier, path: str | None = None
    ) -> list[AutoGeneratedFileData]:
        fields = AutoGeneratedFileSearchableFields.own
        conditions = [fields.is_default.filter.equals(True)]
        if path is not None:
            conditions.append(
                fields.path.filter.equals(
                    StringMatchSpec(value=path, case_insensitive=False, negated=False)
                )
            )
        result = await self._auto_generated_file.search.run(
            SearchAutoGeneratedFilesAction(
                targets=[AutoGeneratedFileTarget.of_owner(owner)],
                searcher=AutoGeneratedFileSearcher(
                    pagination=NoPagination(),
                    conditions=conditions,
                    orders=[fields.created_at.order.apply(True), fields.id.order.apply(True)],
                ),
            )
        )
        return result.items

    async def _default_auto_generated_file_entries(
        self, owner: EntityIdentifier, path: str | None = None
    ) -> list[DotfileEntry]:
        """The owner's default files with their current content, read off the latest revisions."""
        auto_generated_files = await self._search_default_auto_generated_files(owner, path)
        if not auto_generated_files:
            return []
        revisions = await self._auto_generated_file.get_current_revisions.run(
            GetCurrentAutoGeneratedFileRevisionsAction(
                auto_generated_file_ids=[file.id for file in auto_generated_files]
            )
        )
        return [
            DotfileEntry(path=file.path, perm=file.perm, data=revisions.designated[file.id].data)
            for file in auto_generated_files
        ]

    async def create_default_auto_generated_file(
        self, input: CreateAutoGeneratedFileInput
    ) -> GetDotfileResponse:
        """Add a file and make it the default of its path, in two separate writes."""
        created = await self._auto_generated_file.create.run(
            CreateAutoGeneratedFileAction(
                creator=AutoGeneratedFileCreator(
                    owner=input.owner,
                    entry=DotfileEntry(path=input.path, perm=input.perm, data=input.data),
                ),
                creator_id=input.creator_id,
            )
        )
        result = await self._auto_generated_file.switch_default.run(
            SwitchDefaultAutoGeneratedFileAction(
                owner=input.owner, auto_generated_file_id=created.data.id
            )
        )
        return GetDotfileResponse(path=result.data.path, perm=result.data.perm, data=input.data)

    async def get_default_auto_generated_file_by_path(
        self, owner: EntityIdentifier, path: str
    ) -> GetDotfileResponse:
        entries = await self._default_auto_generated_file_entries(owner, path)
        if not entries:
            raise DotfileNotFound
        entry = entries[0]
        return GetDotfileResponse(path=entry.path, perm=entry.perm, data=entry.data)

    async def list_default_auto_generated_files(
        self, owner: EntityIdentifier
    ) -> list[DotfileListItem]:
        entries = await self._default_auto_generated_file_entries(owner)
        return [DotfileListItem(path=e.path, permission=e.perm, data=e.data) for e in entries]

    async def update_default_auto_generated_file(
        self, input: UpdateDefaultAutoGeneratedFileInput
    ) -> GetDotfileResponse:
        DotfilePath(input.path)
        auto_generated_files = await self._search_default_auto_generated_files(
            input.owner, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        result = await self._auto_generated_file.update.run(
            UpdateAutoGeneratedFileAction(
                auto_generated_file_id=auto_generated_files[0].id,
                perm=input.perm,
                revision=AutoGeneratedFileRevisionSpec(
                    data=input.data, creator_id=input.creator_id
                ),
            )
        )
        return GetDotfileResponse(path=result.data.path, perm=result.data.perm, data=input.data)

    async def purge_default_auto_generated_file(
        self, input: DeleteDefaultAutoGeneratedFileInput
    ) -> DeleteDotfileResponse:
        auto_generated_files = await self._search_default_auto_generated_files(
            input.owner, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        await self._auto_generated_file.purge.run(
            PurgeAutoGeneratedFileAction(auto_generated_file_id=auto_generated_files[0].id)
        )
        return DeleteDotfileResponse(success=True)

    async def create(self, input: V2CreateAutoGeneratedFileInput) -> CreateAutoGeneratedFilePayload:
        """Add a file that is not the default of its path, written by the acting user."""
        me = current_user()
        if me is None:
            raise UnreachableError("User context is not available")
        result = await self._auto_generated_file.create.run(
            CreateAutoGeneratedFileAction(
                creator=AutoGeneratedFileCreator(
                    owner=self._scope_entity(input.scope),
                    entry=DotfileEntry(path=input.path, perm=input.permission, data=input.data),
                ),
                creator_id=UserID(me.user_id),
            )
        )
        return CreateAutoGeneratedFilePayload(auto_generated_file=self._to_node(result.data))

    async def purge(self, input: PurgeAutoGeneratedFileInput) -> PurgeAutoGeneratedFilePayload:
        """Remove a file that is not the default of its path; the default is refused.
        The read and the removal are separate, so a default switched in between is not seen."""
        file = await self._auto_generated_file.get.run(
            GetAutoGeneratedFileAction(auto_generated_file_id=input.id)
        )
        if file.data.is_default:
            raise DefaultDotfilePurgeForbidden(
                "Cannot purge the default file of a path. Switch the default first."
            )
        await self._auto_generated_file.purge.run(
            PurgeAutoGeneratedFileAction(auto_generated_file_id=input.id)
        )
        return PurgeAutoGeneratedFilePayload(entity_id=input.id)

    def _to_node(self, file: AutoGeneratedFileData) -> AutoGeneratedFileNode:
        return AutoGeneratedFileNode(
            id=file.id,
            scope_type=self._scope_type(file.entity),
            scope_id=file.entity,
            path=file.path,
            permission=file.perm,
            is_default=file.is_default,
        )

    @staticmethod
    def _scope_entity(ref: AutoGeneratedFileScopeInput) -> EntityIdentifier:
        match ref.scope_type:
            case AutoGeneratedFileScopeType.DOMAIN:
                return DomainID(ref.scope_id)
            case AutoGeneratedFileScopeType.PROJECT:
                return ProjectID(ref.scope_id)
            case AutoGeneratedFileScopeType.USER:
                return UserID(ref.scope_id)
            case _:
                raise UnreachableError(f"No auto-generated file is owned by a {ref.scope_type}")

    @staticmethod
    def _scope_type(owner: EntityIdentifier) -> AutoGeneratedFileScopeType:
        match owner.entity_type():
            case entity_type if entity_type == DomainEntityType():
                return AutoGeneratedFileScopeType.DOMAIN
            case entity_type if entity_type == ProjectEntityType():
                return AutoGeneratedFileScopeType.PROJECT
            case entity_type if entity_type == UserEntityType():
                return AutoGeneratedFileScopeType.USER
            case _:
                raise UnreachableError(
                    f"No auto-generated file is owned by a {owner.entity_type()}"
                )
